package org.diy.watchrecorder;
import android.content.*;import java.io.*;import java.util.*;import org.json.*;import org.diy.lifecore.LocalSecurity;
/** Only finalized, hash-confirmed files can be removed. Incomplete/unreceived recordings are retained. */
final class ArchivePolicy {
 static void write(DataOutputStream out,JSONObject value)throws Exception{byte[] bytes=value.toString().getBytes("UTF-8");if(bytes.length>8*1024*1024)throw new IOException("清单过大");out.writeInt(bytes.length);out.write(bytes);}
 static JSONObject read(DataInputStream in)throws Exception{int size=in.readInt();if(size<2||size>8*1024*1024)throw new IOException("清单大小无效");byte[] bytes=new byte[size];in.readFully(bytes);return new JSONObject(new String(bytes,"UTF-8"));}
 static synchronized JSONArray apply(Context c,JSONObject policy)throws Exception{JSONArray acks=new JSONArray();if(policy==null)return acks;SharedPreferences.Editor processed=c.getSharedPreferences("archive-processed",0).edit();JSONArray ready=policy.optJSONArray("processed");if(ready!=null)for(int i=0;i<ready.length();i++){JSONObject row=ready.getJSONObject(i);processed.putString(row.getString("name"),row.getString("sha"));}if(!processed.commit())throw new IOException("无法保存整理回执");JSONArray commands=policy.optJSONArray("commands");if(commands!=null)for(int i=0;i<commands.length();i++){JSONObject command=commands.getJSONObject(i);String name=command.getString("name"),sha=command.getString("sha");String status="mismatch";if(valid(name)&&sha.matches("[a-f0-9]{64}")){File file=new File(c.getFilesDir(),"recordings/"+name);if(!file.exists())status="absent";else if(new File(file.getPath()+".json").isFile()&&LocalSecurity.hash(file).equals(sha))status=remove(c,file)?"deleted":"failed";}acks.put(new JSONObject().put("id",command.getString("id")).put("name",name).put("sha",sha).put("status",status));}prune(c);return acks;}
 static boolean valid(String name){return name.matches("[A-Za-z0-9_+.:-]{1,220}\\.m4a");}
 static synchronized boolean remove(Context c,File file){if(!file.delete())return false;FinalizedDigest.forget(c,file);new File(file.getPath()+".json").delete();File context=new File(file.getParentFile(),file.getName().replace(".m4a",".context.jsonl"));context.delete();FinalizedDigest.forget(c,context);c.getSharedPreferences("phone-receipts",0).edit().remove(file.getName()).remove(file.getName()+".state").commit();c.getSharedPreferences("archive-processed",0).edit().remove(file.getName()).commit();return true;}
 static synchronized void prune(Context c){File[] files=new File(c.getFilesDir(),"recordings").listFiles((d,n)->valid(n));if(files==null)return;SharedPreferences processed=c.getSharedPreferences("archive-processed",0),receipts=c.getSharedPreferences("phone-receipts",0);for(File file:files)try{File side=new File(file.getPath()+".json");if(!side.isFile())continue;JSONObject meta=new JSONObject(new String(java.nio.file.Files.readAllBytes(side.toPath()),"UTF-8"));long created=meta.optLong("started_at_epoch_ms");String sha=processed.getString(file.getName(),"");
     if(created<=0||System.currentTimeMillis()-created<7L*86400000||sha.isEmpty()||!sha.equals(receipts.getString(file.getName(),"")))continue;
     File context=new File(file.getParentFile(),file.getName().replace(".m4a",".context.jsonl"));boolean contextSaved=!context.isFile()||LocalSecurity.hash(context).equals(receipts.getString(context.getName(),""));if(contextSaved&&sha.equals(LocalSecurity.hash(file)))remove(c,file);
 }catch(Exception ignored){}}
 static JSONObject report(Context c,JSONArray acks)throws Exception{JSONArray inventory=new JSONArray();File[] files=new File(c.getFilesDir(),"recordings").listFiles((d,n)->valid(n));if(files!=null)for(File f:files){File meta=new File(f.getPath()+".json");if(!meta.isFile())continue;JSONObject m=new JSONObject(new String(java.nio.file.Files.readAllBytes(meta.toPath()),"UTF-8"));inventory.put(new JSONObject().put("name",f.getName()).put("sha",FinalizedDigest.get(c,f)).put("bytes",f.length()).put("created",m.optLong("started_at_epoch_ms",f.lastModified())));}return new JSONObject().put("acks",acks).put("files",inventory);}
}
